#' Default parameters for GPU k-means
#'
#' @param k_means_iter Integer. Number of k-means iterations. Defaults to `50L`.
#' @param k_means_init String or `NULL`. Initialisation method. One of
#' `"random"`, `"parallel"`, or `"plusplus"`. If `NULL`, determined on the Rust
#' side. Defaults to `NULL`.
#' @param metric String. The distance metric. One of `c("euclidean", "cosine")`.
#' Defaults to `"euclidean"`.
#' @param fixed Boolean. Shall the algorithm be run for a fixed number of
#' iterations, without checking for convergence. Defaults to `FALSE`.
#' @param quantise Boolean. Whether to quantise data to `fp16` before
#' clustering. This can improve performance in circumstances where it is memory
#' bound. Defaults to `FALSE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k_means_iter - Integer. Number of k-means iterations. Defaults to
#'  `50L`.
#'  \item k_means_init - String or `NULL`. Initialisation method. One of
#'  `"random"`, `"parallel"`, or `"plusplus"`. If `NULL`, determined on the Rust
#'  side. Defaults to `NULL`.
#'  \item metric - String. The distance metric. One of `c("euclidean",
#'  "cosine")`. Defaults to `"euclidean"`.
#'  \item fixed - Boolean. Shall the algorithm be run for a fixed number of
#'  iterations, without checking for convergence. Defaults to `FALSE`.
#'  \item quantise - Boolean. Whether to quantise data to `fp16` before
#'  clustering. This can improve performance in circumstances where it is memory
#'  bound. Defaults to `FALSE`.
#' }
#'
#' @export
params_kmeans_gpu <- function(
  k_means_iter = 50L,
  k_means_init = NULL,
  metric = c("euclidean", "cosine"),
  fixed = FALSE,
  quantise = FALSE
) {
  metric <- match.arg(metric)

  # Checks
  checkmate::qassert(k_means_iter, "I1[1,)")
  checkmate::qassert(k_means_init, c("S1", "0"))
  checkmate::assertChoice(metric, c("euclidean", "cosine"))
  checkmate::qassert(fixed, "B1")
  checkmate::qassert(quantise, "B1")

  if (!is.null(k_means_init)) {
    checkmate::assertChoice(k_means_init, c("random", "parallel", "plusplus"))
  }

  # Return
  list(
    k_means_iter = k_means_iter,
    k_means_init = k_means_init,
    metric = metric,
    fixed = fixed,
    quantise = quantise
  )
}

#' Default parameters for the GPU nearest neighbour backends
#'
#' @description GPU sibling of [bixverse::params_knn_defaults()]. The GPU
#' indices take a different knob set: there is no Annoy and no HNSW on the
#' device, so what survives is exhaustive, IVF and NN-descent.
#'
#' @details
#' NN-descent builds a CAGRA graph and, with `extract_knn = TRUE`, hands that
#' graph back rather than beam searching over it. Note that this saves the
#' query, not the build: the descent itself dominates, and its build degree
#' tracks `k`. NN-descent is therefore a low-`k` tool on the GPU. Above `k` of
#' roughly 30 both exhaustive and IVF beat it, and by `k = 200` they beat it by
#' more than an order of magnitude.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item k - Integer. Number of neighbours. `0L` hands the choice to Rust,
#'  which uses `sqrt(n_cells) * 0.5` and then adjusts for the simulated
#'  doublets. Defaults to `15L`.
#'  \item knn_method - String. The GPU index to use. One of `c("exhaustive",
#'  "ivf", "nndescent")`. Defaults to `"exhaustive"`.
#'  \item ann_dist - String. Manhattan is not supported by the GPU kernels. One
#'  of `c("euclidean", "cosine")`. Defaults to `"euclidean"`.
#'  \item n_list - Integer or `NULL`. IVF only. Number of clusters. `NULL` gives
#'  `sqrt(n)`. Defaults to `NULL`.
#'  \item n_probe - Integer or `NULL`. IVF only. Clusters to probe. `NULL` gives
#'  `sqrt(n_list)`. Defaults to `NULL`.
#'  \item graph_k - Integer or `NULL`. NN-descent only. Node degree of the graph
#'  after pruning. `NULL` gives 30, widened to cover `k` when `extract_knn` is
#'  set. Defaults to `NULL`.
#'  \item k_build - Integer or `NULL`. NN-descent only. Build degree before
#'  pruning. `NULL` gives `max(k, floor(1.5 * k))`. Defaults to `NULL`.
#'  \item n_tree - Integer or `NULL`. NN-descent only. Trees seeding the
#'  descent. Defaults to `NULL`.
#'  \item delta - Numeric. NN-descent only. Termination criterium for the
#'  descent. Defaults to `0.001`.
#'  \item rho - Numeric or `NULL`. NN-descent only. Sampling rate for the
#'  descent. Defaults to `NULL`.
#'  \item refine_knn - Integer or `NULL`. NN-descent only. 2-hop refinement
#'  sweeps after the descent. Buys graph quality at a linear cost. `NULL` gives
#'  0. Defaults to `NULL`.
#'  \item beam_width - Integer or `NULL`. NN-descent only. Beam width when
#'  querying. Ignored when `extract_knn` is set. Defaults to `NULL`.
#'  \item max_beam_iters - Integer or `NULL`. NN-descent only. Beam search
#'  iterations. Ignored when `extract_knn` is set. Defaults to `NULL`.
#'  \item n_entry_points - Integer or `NULL`. NN-descent only. Entry points when
#'  querying. Ignored when `extract_knn` is set. Defaults to `NULL`.
#'  \item extract_knn - Boolean. NN-descent only. Hand back the graph the
#'  descent built instead of beam searching over it. Defaults to `FALSE`.
#' }
#'
#' @export
params_knn_gpu_defaults <- function() {
  list(
    k = 15L,
    knn_method = "exhaustive",
    ann_dist = "euclidean",
    n_list = NULL,
    n_probe = NULL,
    graph_k = NULL,
    k_build = NULL,
    n_tree = NULL,
    delta = 0.001,
    rho = NULL,
    refine_knn = NULL,
    beam_width = NULL,
    max_beam_iters = NULL,
    n_entry_points = NULL,
    extract_knn = FALSE
  )
}

#' Wrapper function for parameters for GPU NEBULA
#'
#' @description GPU counterpart to [bixverse::params_nebula()]. Same knobs and
#' defaults, minus `reml`: the device fit does not implement it. Stage two of
#' NEBULA, the per-gene penalised fits, runs in `f32` on the device and is
#' finished on the host in `f64`, so the estimates sit close to the CPU ones
#' rather than on them.
#'
#' @param nebula_method String. Which variant to run. NEBULA downgrades `"ln"`
#' to `"hl"` below 30 cells per subject, as the R package does. One of `c("ln",
#' "hl")`. Defaults to `"ln"`.
#' @param min_sigma Numeric. Lower bound on the subject-level overdispersion.
#' Defaults to `1e-04`.
#' @param min_phi Numeric. Lower bound on the cell-level overdispersion.
#' Defaults to `1e-04`.
#' @param max_sigma Numeric. Upper bound on the subject-level overdispersion.
#' Defaults to `10.0`.
#' @param max_phi Numeric. Upper bound on the cell-level overdispersion.
#' Defaults to `1000.0`.
#' @param cutoff_cell Numeric. Refit both overdispersions when the product of
#' the cells per subject and the estimated `phi` falls below this. Defaults to
#' `20.0`.
#' @param kappa Numeric. Threshold on NEBULA's `kappa_obs` above which the
#' subject-level overdispersion from stage one is trusted as is. Defaults to
#' `800.0`.
#' @param cpc Numeric. Drop a gene whose mean count per cell is at most this.
#' Defaults to `0.005`.
#' @param mincp Integer. Drop a gene expressed in fewer than this many cells.
#' Defaults to `5L`.
#' @param eps Numeric. Absolute stopping tolerance for the optimiser. Defaults
#' to `1e-06`.
#' @param gene_batch_size Integer. Genes read and fitted per batch. Bounds how
#' much of the store is resident at once and changes nothing about the answer,
#' since NEBULA is gene-independent. Defaults to `1000L`.
#' @param shrink_dispersion Boolean. Shrink the cell-level overdispersions
#' towards an empirical Bayes prior once the sweep is done. Defaults to `TRUE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item nebula_method - String. Which variant to run. NEBULA downgrades `"ln"`
#'  to `"hl"` below 30 cells per subject, as the R package does. One of `c("ln",
#'  "hl")`. Defaults to `"ln"`.
#'  \item min_sigma - Numeric. Lower bound on the subject-level overdispersion.
#'  Defaults to `1e-04`.
#'  \item min_phi - Numeric. Lower bound on the cell-level overdispersion.
#'  Defaults to `1e-04`.
#'  \item max_sigma - Numeric. Upper bound on the subject-level overdispersion.
#'  Defaults to `10.0`.
#'  \item max_phi - Numeric. Upper bound on the cell-level overdispersion.
#'  Defaults to `1000.0`.
#'  \item cutoff_cell - Numeric. Refit both overdispersions when the product of
#'  the cells per subject and the estimated `phi` falls below this. Defaults to
#'  `20.0`.
#'  \item kappa - Numeric. Threshold on NEBULA's `kappa_obs` above which the
#'  subject-level overdispersion from stage one is trusted as is. Defaults to
#'  `800.0`.
#'  \item cpc - Numeric. Drop a gene whose mean count per cell is at most this.
#'  Defaults to `0.005`.
#'  \item mincp - Integer. Drop a gene expressed in fewer than this many cells.
#'  Defaults to `5L`.
#'  \item eps - Numeric. Absolute stopping tolerance for the optimiser. Defaults
#'  to `1e-06`.
#'  \item gene_batch_size - Integer. Genes read and fitted per batch. Bounds how
#'  much of the store is resident at once and changes nothing about the answer,
#'  since NEBULA is gene-independent. Defaults to `1000L`.
#'  \item shrink_dispersion - Boolean. Shrink the cell-level overdispersions
#'  towards an empirical Bayes prior once the sweep is done. Defaults to `TRUE`.
#' }
#'
#' @references He, et al., Commun Biol, 2021
#'
#' @export
params_nebula_gpu <- function(
  nebula_method = c("ln", "hl"),
  min_sigma = 1e-04,
  min_phi = 1e-04,
  max_sigma = 10.0,
  max_phi = 1000.0,
  cutoff_cell = 20.0,
  kappa = 800.0,
  cpc = 0.005,
  mincp = 5L,
  eps = 1e-06,
  gene_batch_size = 1000L,
  shrink_dispersion = TRUE
) {
  nebula_method <- match.arg(nebula_method)

  # Checks
  checkmate::assertChoice(nebula_method, c("ln", "hl"))
  checkmate::qassert(min_sigma, "N1(0,)")
  checkmate::qassert(min_phi, "N1(0,)")
  checkmate::qassert(max_sigma, "N1(0,)")
  checkmate::qassert(max_phi, "N1(0,)")
  checkmate::qassert(cutoff_cell, "N1[0,)")
  checkmate::qassert(kappa, "N1[0,)")
  checkmate::qassert(cpc, "N1[0,)")
  checkmate::qassert(mincp, "I1[0,)")
  checkmate::qassert(eps, "N1(0,)")
  checkmate::qassert(gene_batch_size, "I1[1,)")
  checkmate::qassert(shrink_dispersion, "B1")

  if (min_sigma >= max_sigma) {
    stop("`min_sigma` needs to be below `max_sigma`.")
  }
  if (min_phi >= max_phi) {
    stop("`min_phi` needs to be below `max_phi`.")
  }

  # Return
  list(
    nebula_method = nebula_method,
    min_sigma = min_sigma,
    min_phi = min_phi,
    max_sigma = max_sigma,
    max_phi = max_phi,
    cutoff_cell = cutoff_cell,
    kappa = kappa,
    cpc = cpc,
    mincp = mincp,
    eps = eps,
    gene_batch_size = gene_batch_size,
    shrink_dispersion = shrink_dispersion
  )
}

#' Wrapper function to generate GPU nearest neighbour parameters
#'
#' @param dist_metric String. The distance metric to use. One of `c("euclidean",
#' "cosine")`. Defaults to `"euclidean"`.
#' @param n_list Integer or `NULL`. IVF GPU: Number of clusters to use. If
#' `NULL`, will default to `sqrt(n)`. Defaults to `NULL`.
#' @param n_probes Integer or `NULL`. IVF GPU: Number of clusters to probe. If
#' `NULL`, will default to `sqrt(n_list)`. Defaults to `NULL`.
#' @param node_degree_final Integer or `NULL`. Final node degree of the CAGRA
#' navigational graph. If `NULL`, defaults to `30` on the Rust side. Defaults to
#' `NULL`.
#' @param k_build Integer or `NULL`. Number of k-neighbours during the NNDescent
#' build phase before CAGRA pruning. If `NULL`, defaults to `1.5 *
#' node_degree_final` on the Rust side. (Cannot be smaller than
#' `node_degree_final`) Defaults to `NULL`.
#' @param n_tree Integer or `NULL`. CAGRA GPU: Number of trees for graph build.
#' Automatically if `NULL`. Defaults to `NULL`.
#' @param delta Numeric. CAGRA GPU: Early termination parameter for NN descent.
#' Defaults to `0.001`.
#' @param rho Numeric or `NULL`. CAGRA GPU: Sample rate parameter for NN
#' descent. Defaults to `NULL`.
#' @param beam_width Integer or `NULL`. CAGRA GPU: Beam width for beam search.
#' If not provided will be set to `max(c(k, node_degree_final, 16L)) * 2`.
#' Defaults to `NULL`.
#' @param max_beam_iters Integer or `NULL`. CAGRA GPU: Maximum number of beam
#' search iterations. If not provided, defaults to `3 * beam_width`. Defaults to
#' `NULL`.
#' @param n_entry_points Integer or `NULL`. CAGRA GPU: Number of entry points
#' for beam search. If not provided, defaults to `8L`. Defaults to `NULL`.
#' @param extract_knn Boolean. CAGRA GPU: Skip the beam search and take the
#' graph the NNDescent left it. Faster, slightly lower recall. Ignored by the
#' other two searches. Defaults to `FALSE`.
#'
#' @returns A named list with the following elements:
#' \itemize{
#'  \item dist_metric - String. The distance metric to use. One of
#'  `c("euclidean", "cosine")`. Defaults to `"euclidean"`.
#'  \item n_list - Integer or `NULL`. IVF GPU: Number of clusters to use. If
#'  `NULL`, will default to `sqrt(n)`. Defaults to `NULL`.
#'  \item n_probes - Integer or `NULL`. IVF GPU: Number of clusters to probe. If
#'  `NULL`, will default to `sqrt(n_list)`. Defaults to `NULL`.
#'  \item node_degree_final - Integer or `NULL`. Final node degree of the CAGRA
#'  navigational graph. If `NULL`, defaults to `30` on the Rust side. Defaults
#'  to `NULL`.
#'  \item k_build - Integer or `NULL`. Number of k-neighbours during the
#'  NNDescent build phase before CAGRA pruning. If `NULL`, defaults to `1.5 *
#'  node_degree_final` on the Rust side. (Cannot be smaller than
#'  `node_degree_final`) Defaults to `NULL`.
#'  \item n_tree - Integer or `NULL`. CAGRA GPU: Number of trees for graph
#'  build. Automatically if `NULL`. Defaults to `NULL`.
#'  \item delta - Numeric. CAGRA GPU: Early termination parameter for NN
#'  descent. Defaults to `0.001`.
#'  \item rho - Numeric or `NULL`. CAGRA GPU: Sample rate parameter for NN
#'  descent. Defaults to `NULL`.
#'  \item beam_width - Integer or `NULL`. CAGRA GPU: Beam width for beam search.
#'  If not provided will be set to `max(c(k, node_degree_final, 16L)) * 2`.
#'  Defaults to `NULL`.
#'  \item max_beam_iters - Integer or `NULL`. CAGRA GPU: Maximum number of beam
#'  search iterations. If not provided, defaults to `3 * beam_width`. Defaults
#'  to `NULL`.
#'  \item n_entry_points - Integer or `NULL`. CAGRA GPU: Number of entry points
#'  for beam search. If not provided, defaults to `8L`. Defaults to `NULL`.
#'  \item extract_knn - Boolean. CAGRA GPU: Skip the beam search and take the
#'  graph the NNDescent left it. Faster, slightly lower recall. Ignored by the
#'  other two searches. Defaults to `FALSE`.
#' }
#'
#' @export
params_nn_gpu <- function(
  dist_metric = c("euclidean", "cosine"),
  n_list = NULL,
  n_probes = NULL,
  node_degree_final = NULL,
  k_build = NULL,
