  checkmate::qassert(rho, c("N1", "0"))
  checkmate::qassert(beam_width, c("I1", "0"))
  checkmate::qassert(max_beam_iters, c("I1", "0"))
  checkmate::qassert(n_entry_points, c("I1", "0"))
  checkmate::qassert(extract_knn, "B1")

  # Return
